  "stated_empirical_relation": {
    "component_id": "C014.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The uncertainty concerns the recommendation's scope, not a stated unresolved empirical relation."
    }
  },
  "rationale": "Identifying an actionable obstacle can license a narrowly scoped intervention to test. However, the frozen claim makes obstacle identification necessary for using the release slot for a 'change.' If that term includes diagnostic changes, P012 permits such use without distinguishing an actionable obstacle. If it covers only behavior-changing fixes, the branches are compatible. The frozen scope leaves this distinction unresolved, so a definite judgment would require silently choosing a reading.",
  "uncertainty": "Execution readiness and assumed observations do not resolve which release activities the necessary condition governs.",
  "anomalies": []
